/* @lc app=leetcode id=1850 lang=kotlin */ class Solution { fun nx(s: String): String = (s.length - 2 downTo 0).first { s[it] < s[it + 1] }.let { i -> (s.length - 1 downTo i + 1).first { s[it] > s[i] }.let { j -> s.substring(0, i) + s[j] + (s.substring(i + 1, j) + s[i] + s.substring(j + 1)).toCharArray().sorted().joinToString("") } } fun getMinSwaps(num: String, k: Int): Int = generateSequence(num) { nx(it) }.elementAt(k).let { tg -> StringBuilder(num).let { cur -> tg.indices.sumOf { i -> cur.indexOf(tg[i].toString(), i).let { j -> (j - i).also { cur.deleteCharAt(j).insert(i, tg[i]) } } } } } }